function imageCatalogDescription(name){
  if(imageCatalogDescriptionByName[name]) return imageCatalogDescriptionByName[name];
  if(name.includes("Variante nicht eindeutig lesbar")||name.includes("Duftvariante auf Foto")||name.includes("Parfumvariante auf Foto"))
    return "Die Marke bzw. Produktlinie ist auf dem Foto erkennbar, die genaue Variante ist auf dem Bild jedoch nicht eindeutig lesbar. Deshalb wird hier bewusst keine Variante erfunden.";
  if(name.includes("Parfum-Auswahl"))
    return "Das Foto zeigt mehrere unterschiedliche Düfte gleichzeitig. Ein einzelner Produktname lässt sich daraus nicht seriös einer Flasche zuordnen.";
  if(name.startsWith("Xerjoff")) return "Xerjoff-Nischenduft mit hochwertiger, intensiver Duftkomposition; die genaue Variante ist auf dem Foto nicht eindeutig lesbar.";
  if(name.startsWith("Louis Vuitton")) return "Louis-Vuitton-Nischenduft mit charakteristisch luxuriöser, konzentrierter Komposition; die genaue Variante ist auf dem Foto nicht eindeutig lesbar.";
  if(name.startsWith("Tom Ford")) return "Tom-Ford-Duft mit charakteristisch intensiver, hochwertiger Komposition; die genaue Variante ist auf dem Foto nicht eindeutig lesbar.";
  return "Duftprofil passend zur auf dem Produktfoto erkennbaren Duftlinie; die genaue Variante ist auf dem Bild nicht vollständig lesbar.";
}
const products=Array.from({length:332},(_,i)=>{const id=i+1,name=labels[id]||"ATG Parfum "+String(id).padStart(3,"0"),price=/Louis Vuitton|Xerjoff/.test(name)?100:80;return {id,name,slug:name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")+"-"+String(id).padStart(3,"0"),notes:"Originalprodukt · Duftlinie",price,image:"/product-image/"+id,description:descByName[name]||"Originalabbildung des Duftes "+name+"."};});
products.forEach(p=>{const n=IMAGE_NAME_OVERRIDES[String(p.id)];if(n){p.name=n;p.description=imageCatalogDescription(n);}});
products.forEach(p=>{p.slug=p.name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")+"-"+String(p.id).padStart(3,"0");p.price=/Louis Vuitton|Xerjoff/.test(p.name)?100:80;});
products.sort((a,b)=>a.id-b.id);

// Vollständige visuelle Zuordnung aus product-map.json nachladen.
fetch('/product-map.json').then(r=>r.ok?r.json():null).then(map=>{
  if(!map)return;
  Object.assign(IMAGE_NAME_OVERRIDES,map);
  products.forEach(p=>{const n=IMAGE_NAME_OVERRIDES[String(p.id)];if(n){p.name=n;p.description=imageCatalogDescription(n);p.slug=p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+String(p.id).padStart(3,'0');p.price=/Louis Vuitton|Xerjoff/.test(p.name)?100:80;}});
  products.sort((a,b)=>a.id-b.id);
  if(typeof renderProducts==='function')renderProducts();
  if(typeof renderCart==='function')renderCart();
}).catch(()=>{});

let cart=[];
const euro=n=>n.toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const grid=document.getElementById('products');
const panel=document.getElementById('cartPanel');
const overlay=document.getElementById('overlay');

function renderProducts(list=products){
  grid.innerHTML=list.map(p=>'<article class="atg-card"><div class="atg-visual"><img class="product-image" src="'+p.image+'" alt="'+p.name+'" loading="lazy"></div><div class="atg-body"><h3>'+p.name+'</h3><div class="atg-notes">'+p.notes+'</div><p class="atg-description">'+p.description+'</p><div class="atg-row"><span class="atg-price">'+euro(p.price)+'</span><button class="add" data-id="'+p.id+'">IN DEN WARENKORB</button></div></div></article>').join('');
}
function addToCart(id){const x=cart.find(i=>i.id===id);x?x.qty++:cart.push({id:id,qty:1});renderCart();openCart();}
function changeQty(id,delta){const x=cart.find(i=>i.id===id);if(!x)return;x.qty+=delta;if(x.qty<=0)cart=cart.filter(i=>i.id!==id);renderCart();}
function removeFromCart(id){cart=cart.filter(x=>x.id!==id);renderCart();}
function renderCart(){
  const items=document.getElementById('cartItems'),count=cart.reduce((s,x)=>s+x.qty,0),total=cart.reduce((s,x)=>s+(products.find(p=>p.id===x.id)?.price||0)*x.qty,0);
  document.getElementById('cartCount').textContent=count;
  document.getElementById('cartTotal').textContent=euro(total);
  items.innerHTML=cart.length?cart.map(x=>{const p=products.find(p=>p.id===x.id);return '<div class="cart-item"><div class="cart-item-info"><strong>'+p.name+'</strong><small>'+euro(p.price)+' · '+x.qty+' Stück</small></div><div class="cart-controls"><button type="button" class="qty" data-minus="'+p.id+'">−</button><span>'+x.qty+'</span><button type="button" class="qty" data-plus="'+p.id+'">+</button><button type="button" class="remove" data-remove="'+p.id+'">Entfernen</button></div></div>';}).join(''):'<p class="empty">Dein Warenkorb ist leer.</p>';
  items.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>changeQty(+b.dataset.minus,-1));
  items.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>changeQty(+b.dataset.plus,1));
  items.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeFromCart(+b.dataset.remove));
}
function openCart(){panel.classList.add('open');overlay.classList.add('show');}
function closeCart(){panel.classList.remove('open');overlay.classList.remove('show');}
document.addEventListener('click',e=>{const b=e.target.closest('.add[data-id]');if(b){e.preventDefault();e.stopPropagation();addToCart(Number(b.dataset.id));}});
document.getElementById('cartBtn').onclick=openCart;
document.getElementById('closeCart').onclick=closeCart;
overlay.onclick=closeCart;
function openTelegramCheckout(){document.getElementById('orderModal')?.classList.add('show');}
function closeTelegramCheckout(){document.getElementById('orderModal')?.classList.remove('show');}
document.getElementById('checkoutBtn').onclick=()=>{if(!cart.length){alert('Dein Warenkorb ist leer.');return;}openTelegramCheckout();};
document.getElementById('orderModalClose')?.addEventListener('click',closeTelegramCheckout);
document.getElementById('orderModal')?.addEventListener('click',e=>{if(e.target.id==='orderModal')closeTelegramCheckout();});
document.getElementById('orderForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!cart.length)return;const status=document.getElementById('orderStatus');const btn=e.target.querySelector('button[type="submit"]');btn.disabled=true;status.textContent='Bestellung wird an den ATG Telegram-Bot übergeben …';try{const customer={name:document.getElementById('orderName').value.trim(),email:document.getElementById('orderEmail').value.trim(),address:document.getElementById('orderAddress').value.trim()};const r=await fetch('/api/telegram-order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer,items:cart.map(x=>({id:x.id,qty:x.qty})),telegram_chat_id:(window.Telegram?.WebApp?.initDataUnsafe?.user?.id?String(window.Telegram.WebApp.initDataUnsafe.user.id):'')})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Bestellung konnte nicht erstellt werden.');status.innerHTML='✅ Bestellung '+data.order_number+' erstellt.<br>Öffne jetzt den Telegram-Bot für Rechnung, Wallets/QR-Codes und Zahlungsstatus.';const link=document.getElementById('telegramOrderLink');link.href=data.telegram_url||'#';link.classList.remove('hidden');cart=[];renderCart();}catch(err){status.textContent='❌ '+err.message}finally{btn.disabled=false}});

